       value = function() c(approx(1:4, (1:4)^2, xout = c(1.5, 3.2))$y, spline(1:4, (1:4)^2, xout = c(1.5, 3.2))$y, splinefun(1:4, (1:4)^2, method = "natural")(c(1.5, 3.2), deriv = 1), splinefunH(c(0, 1, 2), c(0, 1, 0), c(1, 0, -1))(c(0.5, 1.5)))),
  list(id = "barylag-hermite", title = "Lagrange interpolation (pracma::barylag) and the Hermite polynomial through values and slopes",
       value = function() c(pracma::barylag(c(0, 1, 2, 4), c(1, 3, 2, 5), c(0.5, 3)), { xi <- c(0, 1, 2); A <- rbind(outer(xi, 0:5, "^"), outer(xi, 0:5, function(x, k) k * x^pmax(k - 1, 0))); a <- solve(A, c(0, 1, 0, 1, 0, -1)); sapply(c(0.5, 1.5), function(v) sum(a * v^(0:5))) })),
  list(id = "ode", title = "Exponential decay by fixed-step Runge-Kutta (deSolve)",
       value = function() deSolve::ode(1, c(0, 0.5, 1, 1.5, 2), function(t, y, p) list(-p[1] * y), 0.7, method = "rk4")[, 2]),
  list(id = "derivatives", title = "Gradient, Jacobian and Hessian by Richardson extrapolation (numDeriv)",
       value = function() c(numDeriv::grad(function(x) x[1] * x[1] * x[2], c(1, 2)), t(numDeriv::jacobian(function(x) c(x[1] * x[2], x[1] + x[2] * x[2]), c(1, 2))), numDeriv::hessian(function(x) x[1] * x[1] * x[2] + x[2] * x[2] * x[2], c(1, 2))))
)

if (!exists(".rstats_oracle")) {
  for (ex in examples) {
    cat(sprintf("%s: %s\n", ex$id, ex$title))
